// Embeds the tier-1 fixtures as Dart constants so tests can load them on
// every platform (VM, AOT, dart2js, dart2wasm) without dart:io.
//
//   dart run tool/fixtures/generate_dart_constants.dart          # write
//   dart run tool/fixtures/generate_dart_constants.dart --check  # verify
//
// Output: packages/ades/test/support/tier1_data.g.dart. The freshness test
// in test/tier1_constants_test.dart runs the same check in CI.
import 'dart:convert';
import 'dart:io';

const outputPath = 'packages/ades/test/support/tier1_data.g.dart';

/// Source text of the generated file for the fixtures under [root].
String generate(String root) {
  final base = Directory(root);
  final files = <String, List<int>>{};
  for (final e in base.listSync(recursive: true)) {
    if (e is! File) continue;
    final rel = e.path.substring(base.path.length + 1).replaceAll('\\', '/');
    final keep =
        (rel.startsWith('signatures/') && !rel.endsWith('.json')) ||
        rel.startsWith('content/') ||
        (rel.startsWith('pki/') && rel.endsWith('.der'));
    if (keep) files[rel] = e.readAsBytesSync();
  }
  final names = files.keys.toList()..sort();
  final b = StringBuffer()
    ..writeln('// GENERATED by tool/fixtures/generate_dart_constants.dart.')
    ..writeln('// Do not edit. Source: fixtures/tier1/.')
    ..writeln('// ignore_for_file: lines_longer_than_80_chars')
    ..writeln()
    ..writeln('/// Base64 of tier-1 fixture files, keyed by path under')
    ..writeln(
      '/// `fixtures/tier1/` (signatures, content and DER certificates).',
    )
    ..writeln('const Map<String, String> tier1Base64 = {');
  for (final n in names) {
    final one = "  '$n': '${base64.encode(files[n]!)}',";
    if (one.length <= 80) {
      b.writeln(one); // dart format joins entries that fit on one line
    } else {
      b.writeln("  '$n':");
      b.writeln("      '${base64.encode(files[n]!)}',");
    }
  }
  b.writeln('};');
  return b.toString();
}

void main(List<String> args) {
  final text = generate('fixtures/tier1');
  final out = File(outputPath);
  if (args.contains('--check')) {
    if (!out.existsSync() || out.readAsStringSync() != text) {
      stderr.writeln('$outputPath is stale: run generate_dart_constants.dart');
      exit(1);
    }
    return;
  }
  out.createSync(recursive: true);
  out.writeAsStringSync(text);
}
